erator = np.sum((x - x_mean) * (y - y_mean))\ndenominator = np.sum((x - x_mean) ** 2)\n\nslope = numerator / denominator\n\nprint(f\"Years: {x}\")\nprint(f\"Q4 Averages (millions): {y}\")\nprint(f\"Mean x: {x_mean}, Mean y: {y_mean}\")\nprint(f\"Numerator: {numerator}\")\nprint(f\"Denominator: {denominator}\")\nprint(f\"Slope: {slope} million dollars per year\")\nprint(f\"Slope rounded to nearest whole number: {round(slope)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
